import { google } from 'googleapis';
import { GeeAuthService } from '../services/gee/GeeAuthService.js';

async function main() {
  const authService = GeeAuthService.getInstance();
  const token = await authService.getAccessToken();
  const config = authService.getConfig();

  console.log('Project ID:', config.projectId);
  console.log('Token exists:', !!token);

  // 1. Test Google Drive API with ADC
  console.log('\n--- Testing Google Drive API with ADC ---');
  try {
    const auth = new google.auth.GoogleAuth({
      scopes: [
        'https://www.googleapis.com/auth/drive.readonly',
        'https://www.googleapis.com/auth/drive',
        'https://www.googleapis.com/auth/cloud-platform'
      ],
    });
    const driveClient = google.drive({ version: 'v3', auth });
    const driveRes = await driveClient.files.list({
      pageSize: 5,
      fields: 'files(id, name, mimeType)',
    });
    console.log('Drive files list success! Found files:', driveRes.data.files?.length);
    driveRes.data.files?.forEach((f) => console.log(`  - ${f.name} (${f.id}) [${f.mimeType}]`));
  } catch (err: any) {
    console.error('Drive files.list error:', err.message);
    if (err.response?.data) {
      console.error('Drive error details:', JSON.stringify(err.response.data));
    }
  }

  // 2. Test GEE image:export endpoint
  console.log('\n--- Testing GEE image:export endpoint ---');
  const imageId = 'COPERNICUS/S2_SR_HARMONIZED/20200109T051201_20200109T051844_T43PHM';
  const exportUrl = `https://earthengine.googleapis.com/v1alpha/projects/${config.projectId}/image:export`;
  console.log('Export URL:', exportUrl);

  const sathiyarPolygon = {
    type: 'Polygon',
    coordinates: [
      [
        [78.07470465117308, 10.118261747031166],
        [78.08672717223784, 10.111838408411883],
        [78.0939406848767, 10.11969852887474],
        [78.08904580130034, 10.123501743888568],
        [78.07977128505037, 10.1228256200689],
        [78.07521990207582, 10.12198046329112],
        [78.07470465117308, 10.118261747031166],
      ],
    ],
  };

  const payload = {
    description: `sathiyar_test_export_${Date.now()}`,
    expression: {
      functionInvocationValue: {
        functionName: 'Image.load',
        arguments: {
          id: { constantValue: imageId },
        },
      },
    },
    fileExportOptions: {
      fileFormat: 'GEO_TIFF',
      driveDestination: {
        folder: 'MonitoringExports',
        filenamePrefix: `sathiyar_test_${Date.now()}`,
      },
    },
  };

  try {
    const res = await fetch(exportUrl, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${token}`,
        'Content-Type': 'application/json',
        'X-Goog-User-Project': config.projectId,
      },
      body: JSON.stringify(payload),
    });

    console.log('Export HTTP Status:', res.status, res.statusText);
    const bodyText = await res.text();
    console.log('Export Response:', bodyText);
  } catch (err: any) {
    console.error('Export fetch error:', err.message);
  }
}

main().catch(console.error);
